      "id": "modern-c04-l19-p01-098",
      "title": "ズデーテン地方割譲の要求",
      "body": [
        "「ドイツ人さえ住んでれば、英仏を黙らせるのは簡単だ……」と思ったヒトラーは、隣国の<strong class=\"source-bold\">チェコスロヴァキア</strong>に対し「国境付近の<strong class=\"source-bold\">ドイツ人居住地</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ズデーテン地方</strong></span>をドイツによこせ！ <ruby>割譲<rt>かつじょう</rt></ruby>しないなら戦争だ！ 戦争か割譲か、チェコスロヴァキアの未来はチェコスロヴァキアが決めろ〜」と<ruby>脅迫<rt>きょうはく</rt></ruby>した。"
      ],
      "plainBody": [
        "「ドイツ人さえ住んでれば、英仏を黙らせるのは簡単だ……」と思ったヒトラーは、隣国のチェコスロヴァキアに対し「国境付近のドイツ人居住地ズデーテン地方をドイツによこせ！ 割譲しないなら戦争だ！ 戦争か割譲か、チェコスロヴァキアの未来はチェコスロヴァキアが決めろ〜」と脅迫した。"
      ],
