      "id": "modern-c04-l19-p01-143",
      "title": "ソ連の進出と冬戦争",
      "body": [
        "そして、ドイツ軍の攻撃が終わると、独ソ<ruby>不可侵<rt>ふかしん</rt></ruby>条約で密約を結んだ<strong class=\"source-bold\">ソ連</strong>も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランドに<ruby>侵攻<rt>しんこう</rt></ruby></strong></span>し、続けて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルト3国</strong></span>も占領すると、さらに11月には<strong class=\"source-bold\">フィンランドにも侵攻</strong>して、<strong class=\"source-bold\">カレリア地方を奪った</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連＝フィンランド戦争</strong></span> <strong class=\"source-bold\">【</strong>冬戦争<strong class=\"source-bold\">】</strong>）。"
      ],
