      "title": "アメリカへの参戦要請と中立法",
      "body": [
        "そしてこの間、<strong class=\"source-bold\">チャーチル</strong>はアメリカのフランクリン＝ローズヴェルト大統領に、「とにかく参戦してくれ！」と訴えたけど、<strong class=\"source-bold\">アメリカ</strong>では「ヨーロッパには<ruby>介入<rt>かいにゅう</rt></ruby>しない」という<strong class=\"source-bold\">孤立主義が強く</strong>、<strong class=\"source-bold\">中立法</strong>があったために<strong class=\"source-bold\">ローズヴェルトは参戦も支援もできなかった</strong>んだ。"
      ],
      "plainBody": [
        "そしてこの間、チャーチルはアメリカのフランクリン＝ローズヴェルト大統領に、「とにかく参戦してくれ！」と訴えたけど、アメリカでは「ヨーロッパには介入しない」という孤立主義が強く、中立法があったためにローズヴェルトは参戦も支援もできなかったんだ。"
      ],
