      "title": "ドイツ軍のバルカン半島進出",
      "body": [
        "一方、イギリス上陸を<ruby>諦<rt>あきら</rt></ruby>めた<strong class=\"source-bold\">ドイツ軍</strong>の標的は、<strong class=\"source-bold\">バルカン半島</strong>へと変わっていた。当時、ソ連が東欧に勢力圏を拡大しようとしていたのに対抗して、ドイツ軍は<strong class=\"source-bold\">ルーマニア、ブルガリア、ユーゴスラヴィア</strong>、さらにはイタリアを助けて<strong class=\"source-bold\">ギリシア</strong>にも進出したんだ。"
      ],
