export const sourcePages = {
  "343": "<h2>343</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第二次世界大戦</strong></span></p>\n<p>それじゃあ、いよいよ<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">第二次世界大戦</strong></u>だよ。ドイツではヒトラー政権が次々と<ruby>侵略<rt>しんりゃく</rt></ruby>を進めていくんだけど、ほかの国はいったい何をしていたんだろう？ そして、人類史上最大の戦争となった第二次世界大戦に突入すると、世界はどうなってしまうんだろう？</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <strong class=\"source-bold\">ドイツの侵略と<br>第二次世界大戦の勃発</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">344〜352ページ</span></td></tr><tr><td><span data-source-marker=\"arrow\" data-source-pattern=\"horizontal-stripes\" data-source-direction=\"down\" data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <strong class=\"source-bold\">第二次世界大戦</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">352〜361ページ</span></td></tr></tbody></table></div>\n<blockquote><p>前半でヒトラーの侵略と各国の対応を、後半では第二次世界大戦を見ていくよ！</p></blockquote>\n<p>1933年に<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヒトラー政権が成立</strong></u>すると、ドイツはどんどん<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">軍備を拡大</strong></u>して、ついに侵略を開始するよ。これに対し各国の足並みは必ずしも揃っていたわけじゃない。特に、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">英仏の<ruby>宥和<rt>ゆうわ</rt></ruby>政策</strong></u>と<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカの孤立主義</strong></u>が、ヒトラーの侵略をさらに激化させたとも考えられる。そして、第二次世界大戦を止めるチャンスは、実は何度もあったはずなのに、世界は<ruby>未<rt>み</rt></ruby><ruby>曾有<rt>ぞう</rt></ruby>の大戦に突入してしまうんだ。<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">第二次世界大戦</strong></u>を経て、世界はどんなふうに変わっていくんだろう？ それじゃあ、第二次世界大戦の始まり〜。</p>",
  "344": "<h2>344</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ドイツの侵略と第二次世界大戦の勃発</strong></span></h3>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"color:#111111;background-color:#f0a0a0\"><strong class=\"source-bold\">ヒトラーの軍事行動とドイツの領土拡大</strong></span></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ザール<ruby>編入<rt>へんにゅう</rt></ruby></strong>［1935］……住民投票で91％の圧倒的な支持を得て、ドイツ領に復帰</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再軍備宣言</strong></span>［1935.3］……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>徴兵制<rt>ちょうへいせい</rt></ruby></strong></span>の復活、<strong class=\"source-bold\">空軍の保有</strong>などを国際的に公言</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span><strong class=\"source-bold\">仏ソ相互援助条約</strong>［1935.5］……仏・ソ連・チェコが反ドイツで連携</p>\n<p><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英独海軍協定</strong></span>［1935.6］……イギリスはドイツの再軍備を容認</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラインラント<ruby>進駐<rt>しんちゅう</rt></ruby></strong></span>［1936.3］……ロカルノ条約の<ruby>破棄<rt>はき</rt></ruby>、非武装地帯にドイツ軍を配備</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スペイン内戦</strong></span>［1936〜39］……「<strong class=\"source-bold\">ファシズム vs.反ファシズム</strong>」となる</p>\n<p><span data-source-color=\"green\" data-source-marker=\"dot\" style=\"color:#859476\">●</span><strong class=\"source-bold\">アサーニャ人民戦線内閣</strong>の成立［1936.2］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>反共和派の軍人：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランコ</strong></span>がモロッコで反乱……軍部・地主・教会が支持</p>\n<p><span data-source-color=\"green\" data-source-marker=\"dot\" style=\"color:#859476\">●</span>各国の対応</p>\n<p><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span><strong class=\"source-bold\">独（ヒトラー）・伊（ムッソリーニ）がフランコ側を支援</strong>して参戦</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゲルニカ爆撃</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ピカソ</strong></span>は怒りを込めて「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゲルニカ</strong></span>」を創作</p>\n<p><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span><strong class=\"source-bold\">ソ連は人民戦線政府を支援</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際<ruby>義勇軍<rt>ぎゆうぐん</rt></ruby></strong></span>への参加を呼びかけた</p>\n<p><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span><strong class=\"source-bold\">英仏</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>不干渉<rt>ふかんしょう</rt></ruby>政策</strong></span></p>\n<p><span data-source-color=\"green\" data-source-marker=\"dot\" style=\"color:#859476\">●</span>内戦の終結……マドリード<ruby>陥落<rt>かんらく</rt></ruby>で<strong class=\"source-bold\">フランコが勝利</strong>［1939.3］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>日独伊の接近＝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三国枢軸</strong></span></p>\n<p><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン＝ローマ<ruby>枢軸<rt>すうじく</rt></ruby></strong></span>［1936］……スペイン内戦を機に独・伊が接近</p>\n<p><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日独防共協定</strong></span>［1936.11］……<ruby>満洲事変<rt>まんしゅうじへん</rt></ruby>後に孤立した日本と「<strong class=\"source-bold\">反ソ連</strong>」で連携</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日独伊三国防共協定</strong></span>［1937.11］……名目上は「<strong class=\"source-bold\">反ソ連・反共産主義</strong>」</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>ドイツ人居住地への侵略……東方への生存圏拡大の計画を表明［1937.11］</p>\n<p><span data-source-color=\"green\" data-source-marker=\"dot\" style=\"color:#859476\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア<ruby>併合<rt>へいごう</rt></ruby></strong></span>［1938.3］……「大ドイツ共和国」を実現</p>\n<p><span data-source-color=\"green\" data-source-marker=\"dot\" style=\"color:#859476\">●</span><strong class=\"source-bold\">チェコスロヴァキア</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ズデーテン地方</strong></span>の<ruby>割譲<rt>かつじょう</rt></ruby>要求［1938.9］</p>\n<p><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span><strong class=\"source-bold\">イギリス</strong>首相<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネヴィル＝チェンバレン</strong></span>は、<strong class=\"source-bold\">ドイツとの戦争回避</strong>を画策</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミュンヘン会談</strong></span>［1938.9］……英仏は、ドイツの要求をほぼ全面的に認める</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>ドイツ人居住地以外の東欧への<ruby>侵略<rt>しんりゃく</rt></ruby></p>\n<p><span data-source-color=\"green\" data-source-marker=\"dot\" style=\"color:#859476\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキア解体</strong></span>［1939.3］……チェコ（ベーメン・メーレン）を保護領、スロヴァキアを保護国とした</p>\n<p><span data-source-color=\"green\" data-source-marker=\"dot\" style=\"color:#859476\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド<ruby>回廊<rt>かいろう</rt></ruby></strong></span>の通過権要求、<strong class=\"source-bold\">ダンツィヒ</strong>の返還（併合）要求［1939.3〜］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>独ソの接近と第二次世界大戦の<ruby>勃発<rt>ぼっぱつ</rt></ruby></p>\n<p><span data-source-color=\"green\" data-source-marker=\"dot\" style=\"color:#859476\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独ソ<ruby>不可侵<rt>ふかしん</rt></ruby>条約</strong></span>［1939.8.23］……独の<strong class=\"source-bold\">ヒトラー</strong>とソ連の<strong class=\"source-bold\">スターリン</strong>が突如<ruby>締結<rt>ていけつ</rt></ruby></p>\n<p><span data-source-color=\"gray\" data-source-marker=\"triangle\" style=\"color:#a6aaa0\">▶</span>同時に、<strong class=\"source-bold\">ポーランドと東欧での勢力範囲</strong>を決定</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ軍のポーランド<ruby>侵攻<rt>しんこう</rt></ruby></strong></span>［1939.9］＝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第二次世界大戦</strong></span>勃発</p></blockquote>",
  "345": "<h2>345</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ドイツの侵略と第二次世界大戦の勃発</u></p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ヒトラー政権が成立すると、まずは軍部の要請で国際連盟を脱退！</strong></span></h3>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒトラー政権</strong></span>の成立直後には、軍部や保守派がそれなりに力を持っていたから、初期の外交には<strong class=\"source-bold\">軍部の意見も影響</strong>しているよ。ドイツの軍部はずっと「ドイツだけがヴェルサイユ条約で軍備制限されてるのはおかしい」って主張してたから、ヒトラーは1933年10月に軍事平等権を認めない<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連盟を脱退</strong></span>したんだ。すでに<strong class=\"source-bold\">日本が国際連盟を脱退</strong>しているから、「その手があったか！」って思ったんだろうね。さらに、<strong class=\"source-bold\"><ruby>賠償金<rt>ばいしょうきん</rt></ruby>支払いも一方的に破棄</strong>した。でも、初期の外交ではこれ以外に目立った行動はしないよ。まずは「国内での権力を固めるのが先」だ。</p>\n<p>ただ、これでも<strong class=\"source-bold\">フランスには衝撃</strong>だった。入試レベルじゃないけど、ヒトラーはフランスの反発を予想して、ポーランドとの友好関係を強めたんだもん。ドイツが最初に攻め込むとしたら隣のフランスかポーランドでしょ！。そこで<strong class=\"source-bold\">フランスはソ連に接近</strong>、イギリスも説得して<strong class=\"source-bold\">ソ連を国際連盟に加盟</strong>させた。ここは「<strong class=\"source-bold\">ドイツと入れ替えにソ連が国際連盟に入った</strong>」っておさえておこう！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ヴェルサイユ条約を一方的に破棄して、軍備拡大を公言！</strong></span></h3>\n<p>1934年にヒンデンブルク大統領が亡くなると、ヒトラーは<ruby>総統<rt>そうとう</rt></ruby><strong class=\"source-bold\">【</strong>フューラー<strong class=\"source-bold\">】</strong>に就任したよね。そして、1935年にはいよいよ具体的な行動を始めるよ。まずは<strong class=\"source-bold\">ザールの編入</strong>だ。ザール地方は炭鉱地帯で、ここで採れた石炭はフランスへの賠償になってたんだけど、ヴェルサイユ条約で<strong class=\"source-bold\">15年間国際連盟</strong>（というかフランス）<strong class=\"source-bold\">が管理</strong>することになり、その後<strong class=\"source-bold\">住民投票</strong>でドイツかフランスに<ruby>帰属<rt>きぞく</rt></ruby>を決めることになってたんだ。ヒトラーは、ザール編入が各国の反発を招かないように、住民投票をやるまでは目立たないようにしていて、結果は9割以上が「ドイツのほうがいい」って投票した。だって、<strong class=\"source-bold\">ドイツのほうが失業対策が進んでいた</strong>からね。</p>\n<p>こうして、まんまとザールを手に入れたヒトラーは、同じ年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">徴兵制</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">義務兵役制</strong></span>）の復活を宣言した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再軍備宣言</strong></span>）。さらに、<strong class=\"source-bold\">空軍の保有</strong>を明らかにすると、国防軍を50万人まで増やすって公言した。これは軍備制限を定めた<strong class=\"source-bold\">ヴェルサイユ条約への挑戦</strong>だよ。これに対し、<strong class=\"source-bold\">イギリス・フランス・イタリア</strong>の3国は共同でドイツを批判した（ストレーザ戦線）。でも、この3国は考えてることがバラバラだよ……。だいたい<strong class=\"source-bold\">イタリア</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムッソリーニ</strong></span>政権でしょ！。当時、イタリアはオーストリアをめぐってドイツと<ruby>揉<rt>も</rt></ruby>めてたから一応批判したけど、ファシズムって意味では似た者同士だから、たいして本気じゃない。一番焦ってたのはフランスだ！</p>\n<blockquote><p>再軍備宣言への対応の時点で、すでにイギリスは<ruby>宥和<rt>ゆうわ</rt></ruby>政策を始めるんだよ</p></blockquote>\n<p><strong class=\"source-bold\">フランスは仏ソ相互援助条約</strong>、さらに<strong class=\"source-bold\">フランスとチェコ</strong>、<strong class=\"source-bold\">ソ連とチェコ</strong>も<strong class=\"source-bold\">相互援助条約</strong>を結んで、<strong class=\"source-bold\">ソ連・チェコスロヴァキア</strong>とともにドイツを挟み撃ちにする体制</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "346": "<h2>346</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<p>をつくったよ。一方、<strong class=\"source-bold\">ソ連のスターリン</strong>も<strong class=\"source-bold\">コミンテルン第7回大会</strong>で、反ファシズム勢力を結集する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民戦線</strong></span>戦術を<ruby>採択<rt>さいたく</rt></ruby>したよね。ヒトラーは「共産党もソ連も全部<ruby>潰<rt>つぶ</rt></ruby>す」って言ってたから、ソ連も黙って見てるわけにはいかないよ。これにイギリスが加われば、ヒトラーの暴走は止められただろうね。</p>\n<p>でも<strong class=\"source-bold\">イギリスの動きは逆</strong>だよ。イギリスは「戦争だけは回避したい」って思っていたから、<strong class=\"source-bold\">ドイツとの関係を悪化させない</strong>ことばかり考えていた。しかもヒトラーは「ソ連を潰す！」って言ってるから、攻めるならソ連だろう……。こう考えたイギリスの<strong class=\"source-bold\">ボールドウィン内閣</strong>は、「イギリスの35％までドイツの海軍力を認めよ！」というヒトラーの要求を認める<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英独海軍協定</strong></span>を結んだ。これって、<strong class=\"source-bold\">イギリス自身がヴェルサイユ条約を無視</strong>したってことだよね。こんなふうに、ドイツの<strong class=\"source-bold\">反共反ソの主張に期待</strong>して、<strong class=\"source-bold\">戦争回避</strong>のために<strong class=\"source-bold\">ドイツの無法行為や<ruby>侵略<rt>しんりゃく</rt></ruby>行為を黙認</strong>する外交が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>宥和<rt>ゆうわ</rt></ruby>政策</strong></span>だ。しかもイギリスは、「ヒトラーが自分から要求して結んだ条約なら守るだろ」って期待していたんだけど、これが甘かった。以後、英仏がダラダラと宥和政策を続けてる間に、ヒトラーが侵略を進めるんだもん。</p>\n<p>そして、同じ年の10月に<strong class=\"source-bold\">イタリアのムッソリーニ</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エチオピア侵略</strong></span>をおこなうと、<strong class=\"source-bold\">英仏はこれを激しく批判</strong>！ ストレーザ戦線は<ruby>崩壊<rt>ほうかい</rt></ruby>しちゃった。そしてイタリアの侵略に全世界が注目しているのにつけこんで、ヒトラーは次の行動を起こしたんだ。</p>\n<h4><strong class=\"source-bold\">〈ヒトラーの侵略〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><strong class=\"source-bold\">フィンランド</strong></td></tr><tr><td><strong class=\"source-bold\">エストニア</strong></td></tr><tr><td><strong class=\"source-bold\">ラトヴィア</strong></td></tr><tr><td><strong class=\"source-bold\">リトアニア</strong></td></tr><tr><td>東プロイセン<br>（ドイツ領の飛び地）</td></tr><tr><td><strong class=\"source-bold\">イギリス</strong></td></tr><tr><td><strong class=\"source-bold\">オランダ</strong></td></tr><tr><td><strong class=\"source-bold\">ドイツ</strong></td></tr><tr><td><strong class=\"source-bold\">ポーランド</strong></td></tr><tr><td><strong class=\"source-bold\">フランス</strong></td></tr><tr><td><strong class=\"source-bold\">ハンガリー</strong></td></tr><tr><td><strong class=\"source-bold\">ルーマニア</strong></td></tr><tr><td><strong class=\"source-bold\">ユーゴスラヴィア</strong></td></tr><tr><td><strong class=\"source-bold\">ブルガリア</strong></td></tr><tr><td><strong class=\"source-bold\">スペイン</strong></td></tr><tr><td><strong class=\"source-bold\">イタリア</strong></td></tr><tr><td><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td><strong class=\"source-bold\">トルコ</strong></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">①ザール編入</span> <span data-source-marker=\"dot\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">②ラインラント進駐</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">③スペイン内戦に介入</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">④オーストリア併合</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">⑤ズデーテン地方割譲</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">⑥チェコスロヴァキア解体</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">⑦メーメル併合</span> <span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">⑧ダンツィヒ返還要求</span> <span data-source-marker=\"dot\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">⑧ポーランド回廊の通過権要求</span></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"green\" style=\"border:1px solid #859476;padding:0 0.2em\">※数字は時代順</span></p></blockquote>",
  "347": "<h2>347</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ドイツの侵略と第二次世界大戦の勃発</u></p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ <ruby>賭<rt>か</rt></ruby>けに出たヒトラーは、ラインラントにドイツ軍を配備！</strong></span></h3>\n<p>1936年に入り、ヒトラーは大きな賭けに出た。それが、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルサイユ条約</strong></span>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロカルノ条約</strong></span>で<strong class=\"source-bold\">非武装地帯とされていたラインラントへのドイツ軍の配備</strong>、いわゆる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラインラント<ruby>進駐<rt>しんちゅう</rt></ruby></strong></span>だ。なんで賭けかって？ そりゃ、当時のドイツ軍はまだ戦車も持っていないから、フランス軍が本気出したら絶対負けるからね。でもヒトラーは「フランスに戦争をする覚悟はないだろうし、ドイツ領内だからイギリスは動かないだろう……」と考え、「<strong class=\"source-bold\">仏ソ相互援助条約は、現状維持を決めたロカルノ条約に違反している</strong>」と主張して、ラインラントに軍を進駐させたんだ。</p>\n<blockquote><p>フランス軍が動いたら、ヒトラーは軍を撤退させてたよ。ヒトラーの暴走を止めるチャンスを逃したんだ！</p></blockquote>\n<p>結果は……ヒトラーが賭けに勝った。この時、単独でも戦えるはずのフランスは軍を動かさず、イギリスもラインラントのために戦争する気はなかった。結局、<strong class=\"source-bold\">英仏がドイツのラインラント進駐を黙認</strong>したから、<strong class=\"source-bold\">ヒトラーは宥和政策を見抜き</strong>、急速に軍備拡大を進めるんだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ファシズムvs.反ファシズム。スペイン内戦は第二次世界大戦の<ruby>前哨戦<rt>ぜんしょうせん</rt></ruby>だ！</strong></span></h3>\n<p>ラインラント進駐と同じ年に起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スペイン内戦</strong></span>は、第二次世界大戦前の国際関係に大きな影響を与えたよ。まずは内戦前の<strong class=\"source-bold\">スペイン</strong>の状況を話しておこう。</p>\n<p>スペインでは、第一次世界大戦中から下層労働者のデモやストライキが激化し、さらに植民地のモロッコでも民族運動が起きて、国内が大混乱！ そして1923年には<strong class=\"source-bold\">プリモ＝デ＝リベラ将軍がクーデタで<ruby>独裁<rt>どくさい</rt></ruby>者</strong>となり、むりやり混乱を抑え込んだ。でもだんだんと独裁に反対する運動が激しくなって、1931年にプリモ将軍は辞任に追い込まれ、国王アルフォンソ13世（<strong class=\"source-bold\">ブルボン家</strong>）も<ruby>亡命<rt>ぼうめい</rt></ruby>して<strong class=\"source-bold\">スペインは共和国になった（スペイン革命）</strong>。でも、共和国が進めようとした改革に地主や軍部、教会などの保守派が反発し、<strong class=\"source-bold\">右派と左派が対立</strong>した。そして、<strong class=\"source-bold\">アサーニャ</strong>を大統領とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民戦線内閣</strong></span>が成立すると、対立は頂点に達したんだ。</p>\n<p>1936年7月、人民戦線政府に対して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランコ</strong></span>将軍が指揮する<strong class=\"source-bold\">モロッコ</strong>の陸軍将校団が反乱を起こすと、スペイン本土の陸軍も挙兵して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スペイン内戦</strong></span>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>した。この時、<strong class=\"source-bold\">人民戦線政府はフランスに援助を頼んだ</strong>よ。ほら！ <strong class=\"source-bold\">フランスもブルムの人民戦線内閣</strong>だもんね。でも、フランスでも右派と左派の対立から政局が混乱して支援できず、イギリスも「あくまで“スペイン”の国内問題だから、国際対立にはしない」と言って<ruby>介入<rt>かいにゅう</rt></ruby>しなかった。そして、イギリスの主導で<strong class=\"source-bold\">スペイン内戦<ruby>不干渉<rt>ふかんしょう</rt></ruby>委員会</strong>が設置されると、<strong class=\"source-bold\">英仏</strong>、<strong class=\"source-bold\">ドイツやイタリア</strong>、さらに<strong class=\"source-bold\">ソ連</strong>も参加したんだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "348": "<h2>348</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<h4><strong class=\"source-bold\">〈スペイン内戦〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #111111;padding:0 0.2em\"><strong class=\"source-bold\">ドイツ<br>（ヒトラー）</strong></span><br><span data-source-border=\"black\" style=\"border:1px solid #111111;padding:0 0.2em\"><strong class=\"source-bold\">イタリア<br>（ムッソリーニ）</strong></span></td><td><span data-source-marker=\"double-line\" data-source-color=\"black\" style=\"color:#111111\">═</span><br><span data-source-marker=\"double-line\" data-source-color=\"black\" style=\"color:#111111\">═</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #111111;padding:0 0.2em\"><strong class=\"source-bold\">フランコ<br>（ファシズム）</strong></span></td><td><span data-source-marker=\"double-arrow\" data-source-color=\"black\" style=\"color:#111111\">↔</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">人民戦線<br>（反ファシズム）</strong></span></td><td><span data-source-marker=\"double-line\" data-source-color=\"red\" style=\"color:#e52715\">═</span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ソ連<br>（スターリン）</strong></span></td></tr><tr><td></td><td></td><td></td><td></td><td><span data-source-marker=\"curved-arrow\" data-source-direction=\"down-left\" data-source-color=\"red\" style=\"color:#e52715\">↙</span> <strong class=\"source-bold\">国際義勇軍</strong></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td><span data-source-marker=\"dashed-boundary\" data-source-color=\"brown\" style=\"color:#a43725\">┄</span><br><span data-source-border=\"brown\" style=\"border:1px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">イギリス</strong></span> <span data-source-border=\"brown\" style=\"border:1px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">フランス</strong></span><br><strong class=\"source-bold\">不干渉政策</strong></td><td></td></tr></tbody></table></div>\n<p>でも、<strong class=\"source-bold\">ヒトラーやムッソリーニ</strong>は堂々とフランコを支援し、これをきっかけに仲良くなっちゃった。また、<strong class=\"source-bold\">ポルトガル</strong>の<ruby>独裁<rt>どくさい</rt></ruby>者<strong class=\"source-bold\">サラザール</strong>もフランコを支援した。「<ruby>不干渉<rt>ふかんしょう</rt></ruby>だ！」って言ってるのに、フランコを助ける国はどんどん出てくるね。さらに<strong class=\"source-bold\">ヒトラー</strong>は、スペイン内戦を開発中の<strong class=\"source-bold\">新兵器の実験場</strong>として使ったんだ。例えば、バスク地方の小都市<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゲルニカ</strong></span>への爆撃は、都市への空爆を試すためにおこなわれたものだ。これに激怒したスペイン人画家の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ピカソ</strong></span>は、有名な「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゲルニカ</strong></span>」を描き、のちに「ナチスを倒したい！」と思って<strong class=\"source-bold\">フランス共産党に入った</strong>よ。</p>\n<p>独伊がフランコを支援してるのに<strong class=\"source-bold\">英仏両国</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">不干渉</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非介入</strong></span>）<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">政策</strong></span>を続けた。<strong class=\"source-bold\">ソ連だけが人民戦線政府を支援</strong>し、さらにコミンテルンを通じて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際<ruby>義勇軍<rt>ぎゆうぐん</rt></ruby></strong></span><strong class=\"source-bold\">【</strong>国際旅団<strong class=\"source-bold\">】</strong>への参加を呼びかけると、<strong class=\"source-bold\">ヘミングウェー</strong>（米）、<strong class=\"source-bold\">マルロー</strong>（仏）、<strong class=\"source-bold\">オーウェル</strong>（英）などの知識人が数多く義勇軍に参加したよ。これは、<strong class=\"source-bold\">コミンテルン</strong>が「<strong class=\"source-bold\">反ファシズム勢力を結集</strong>しよう！」って言ってたからだ。こんなふうにスペイン内戦は、「<strong class=\"source-bold\">ファシズム（フランコ）vs.反ファシズム（人民戦線）</strong>」の対立になったから、「<strong class=\"source-bold\">第二次世界大戦の<ruby>前哨戦<rt>ぜんしょうせん</rt></ruby></strong>」ともいわれるよ。ただ、ソ連が支援したことで、英仏では「共産勢力だったら助けなくていいだろ」という世論が起きちゃった。</p>\n<p>最終的には、1939年にファシズム色を強めた<strong class=\"source-bold\">フランコが勝利</strong>し、彼を党首とする<strong class=\"source-bold\">ファランヘ党</strong>の一党独裁体制がつくられた。そして、スペインは<strong class=\"source-bold\">第二次世界大戦で中立</strong>を保ったから戦後もファシズム体制が残り、<strong class=\"source-bold\">フランコが亡くなる1975年までファシズム体制が続く</strong>んだよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 国際的に孤立したドイツ、イタリア、そして日本が接近！</strong></span></h3>\n<p><strong class=\"source-bold\">イタリアのエチオピア<ruby>侵略<rt>しんりゃく</rt></ruby></strong>に対し、国際連盟は経済<ruby>制裁<rt>せいさい</rt></ruby>を始めた。また、<strong class=\"source-bold\">アメリカ</strong>は「ヨーロッパで戦争が起きても助けてやんないからな」と<strong class=\"source-bold\">孤立主義</strong>を強め、1935年には<strong class=\"source-bold\">中立法</strong>を制定してイタリアへの戦略物資の輸出をストップした。各国の制裁で行き詰ったイタリアは、スペイン内戦への参戦で英仏との関係修復も不可能になったから、残された道はドイツとの連携しかない。こうして<strong class=\"source-bold\">ヒトラーとムッソリーニが急接近</strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン＝ローマ<ruby>枢軸<rt>すうじく</rt></ruby></strong></span>が形成されたんだ。</p>\n<p>一方、アジアでも<strong class=\"source-bold\"><ruby>満洲事変<rt>まんしゅうじへん</rt></ruby>後に国際連盟を脱退</strong>した日本が、「<strong class=\"source-bold\">反共産主義</strong>」を主</p>",
  "349": "<h2>349</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ドイツの侵略と第二次世界大戦の勃発</u></p>\n<p>張する<strong class=\"source-bold\">ドイツ</strong>と接近し<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日独<ruby>防共<rt>ぼうきょう</rt></ruby>協定</strong></span>を結んだ。これは「<strong class=\"source-bold\">反ソ連・反コミンテルン</strong>で連携しよう」ってことね。ヒトラーは「反ソ連って言っとけば、イギリスは黙ってるだろ」って思ってたんだけどさ。そして、これに<strong class=\"source-bold\">イタリアも加わって</strong>、1937年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日独伊三国防共協定</strong></span>が成立し、同じ年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリアは国際連盟を脱退</strong></span>した！。こうして、第二次世界大戦における<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三国枢軸</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">枢軸国</strong></span>）が形成されたんだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ヒトラーが領土拡大を開始。まずは「大ドイツ国家」の実現だ！</strong></span></h3>\n<p>国際的な孤立を解消した<strong class=\"source-bold\">ヒトラー</strong>は、<strong class=\"source-bold\">いよいよ対外侵略</strong>を始めた。ヒトラーは「<strong class=\"source-bold\">ドイツ人の住んでるところは全部ドイツに</strong><ruby>併合<rt>へいごう</rt></ruby>する」、つまり「大ドイツ国家」を実現して、さらに東欧にドイツ人の「<strong class=\"source-bold\">生存圏</strong>」を確保しようとしたんだ。これは『わが闘争』のころからずっと言ってることだ。</p>\n<blockquote><p>ドイツ人が住んでればドイツって……。でも、これはドイツ人の「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>」ってことだよね</p></blockquote>\n<p>最初に狙われたのは「ドイツ人国家」の<strong class=\"source-bold\">オーストリア</strong>。もともと、ドイツとイタリアはオーストリア（南チロルの国境問題だ）をめぐって対立してたんだけど、ドイツと連携したムッソリーニは「オーストリアに手は出さない」と言うしかなくなった。こうしてヒトラーは、オーストリアのナチスに「ドイツだけが<ruby>恐慌<rt>きょうこう</rt></ruby>対策に成功している！」と宣伝させ、オーストリア政府に対し「<ruby>属国<rt>ぞっこく</rt></ruby>になれ」と脅しをかけた。この時、オーストリア政府が国民投票で独立を確認しようとしたから、怒ったヒトラーは軍を派遣したんだ。オーストリア国民は「ドイツに併合されれば、仕事がもらえる」と思ったんだろうね、<strong class=\"source-bold\">国民投票でも圧倒的多数の支持</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリア併合</strong></span>が承認された。これ以後、ヒトラーはドイツを「<strong class=\"source-bold\">大ドイツ共和国</strong>」って呼んだよ。<strong class=\"source-bold\">両国の<ruby>合併<rt>がっぺい</rt></ruby>はヴェルサイユ条約で禁止</strong>されていたのに、「ドイツ人が1つの国になっただけ」として、<strong class=\"source-bold\">英仏はそのまま黙認</strong>してしまったんだ。ちなみに、映画「サウンド・オブ・ミュージック」は、ナチスのオーストリア併合が題材だよ。興味があったら観てごらん。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 見捨てられたチェコスロヴァキア。英仏の<ruby>宥和<rt>ゆうわ</rt></ruby>政策もここまできたか！</strong></span></h3>\n<p>オーストリア併合に成功したヒトラーは、ますます調子に乗ってきた。「ドイツ人さえ住んでれば、英仏を黙らせるのは簡単だ……」と思ったヒトラーは、隣国の<strong class=\"source-bold\">チェコスロヴァキア</strong>に対し「国境付近の<strong class=\"source-bold\">ドイツ人居住地</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ズデーテン地方</strong></span>をドイツによこせ！ <ruby>割譲<rt>かつじょう</rt></ruby>しないなら戦争だ！ 戦争か割譲か、チェコスロヴァキアの未来はチェコスロヴァキアが決めろ〜」と<ruby>脅迫<rt>きょうはく</rt></ruby>した。そしてヒトラーは、ズデーテン地方のドイツ人が<ruby>迫害<rt>はくがい</rt></ruby>されているとさんざん宣伝し、国境付近にドイツ軍を移動させたんだ。</p>\n<p>こうなると、いつ戦争が起きてもおかしくない。でも、ボールドウィンにかわって<strong class=\"source-bold\">イギリス首相</strong>となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネヴィル＝チェンバレン</strong></span>（南アフリカ戦争をやったジョゼ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "350": "<h2>350</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<p>フ＝チェンバレンの息子だ）は、「<strong class=\"source-bold\">とにかく戦争回避が最優先</strong>……」として2回もドイツを訪問している。しかし<strong class=\"source-bold\">ヒトラー</strong>は、「<strong class=\"source-bold\">ズデーテンを<ruby>割譲<rt>かつじょう</rt></ruby>しないなら、チェコスロヴァキアを攻撃する</strong>までだ」と繰り返した。こりゃ、戦争が始まっちゃうよ。一方、<strong class=\"source-bold\">フランスやチェコスロヴァキアと相互援助条約</strong>を結んでいた<strong class=\"source-bold\">ソ連のスターリン</strong>は、「ドイツとチェコスロヴァキアの戦争が起きたら、いつでも参戦する」って英仏に伝えたよ。もしこの時、英仏が戦争をする覚悟を決めていたら、ソ連も参戦するからドイツは挟み撃ち！ おそらくドイツは負けていただろうね。ここまできたのに、チェンバレンは戦争を回避したい……と、ムッソリーニに「<strong class=\"source-bold\">首脳会談による解決</strong>」を依頼したんだ。そして、ヒトラーもこれに応じたので、<strong class=\"source-bold\">英仏独伊の4国首脳会談</strong>が開かれることになった。</p>\n<p>1938年9月、<strong class=\"source-bold\">ドイツのミュンヘンで緊急首脳会談</strong>が開かれた。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミュンヘン会談</strong></span>に参加したのは、イギリス首相<strong class=\"source-bold\">ネヴィル＝チェンバレン</strong>、フランス首相<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダラディエ</strong></span>、それに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒトラー</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムッソリーニ</strong></span>だ。この席上でヒトラーは、「<strong class=\"source-bold\">ズデーテンは、ヨーロッパで最後の領土要求</strong>だ」と声高に言い切った。これを聞いた英仏は、ムッソリーニが示した提案（というか、ヒトラーがつくった要求）を承認することを決め、4国は<strong class=\"source-bold\">ミュンヘン協定</strong>に調印した。これで、<strong class=\"source-bold\">ズデーテン地方のドイツへの割譲が決まった</strong>んだよ。<strong class=\"source-bold\">会議に招かれなかったチェコスロヴァキア</strong>は英仏にも見放されて、要求をそのままのむしかなくなった。国境の<ruby>要塞<rt>ようさい</rt></ruby>地帯を失ったチェコスロヴァキアは、もはや国を防衛する力がなくなり、失意のうちに<strong class=\"source-bold\">ベネシュ大統領</strong>は辞任した。このミュンヘン会談での英仏の対応は、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>宥和<rt>ゆうわ</rt></ruby>政策</strong></span>の典型っていわれるよ。</p>\n<p>そしてもう1国、<strong class=\"source-bold\">会議に招かれなかったのがソ連</strong>だよ。<strong class=\"source-bold\">スターリン</strong>は「英仏とドイツが、ソ連を<ruby>封<rt>ふう</rt></ruby>じ込めるために密約を結んだのでは？」と疑い、<strong class=\"source-bold\">英仏への不信感を強めた</strong>。そんな密約はなかったけど、このことがあとで大事件になるよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ヒトラーが再び東欧への侵略を開始。ついに第二次世界大戦が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！</strong></span></h3>\n<p><strong class=\"source-bold\">ヒトラー</strong>は、「ズデーテン地方は最後の領土要求だ！」って大見得を切ったんだけど、そんな<strong class=\"source-bold\">約束を守る気はない</strong>！。1939年に入るとヒトラーは、スロヴァキアで起きていた民族運動を口実に、<strong class=\"source-bold\">チェコスロヴァキア</strong>に対し「スロヴァキアを独立させないと首都のプラハを爆撃するぞ」と脅迫して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキア解体</strong></span>に同意させた。こうしてドイツは、西半分の<strong class=\"source-bold\">チェコを「ベーメン・メーレン保護領」</strong>として<ruby>併合<rt>へいごう</rt></ruby>し、東半分の<strong class=\"source-bold\">スロヴァキアを保護国</strong>にした。さらに国境を接する<strong class=\"source-bold\">リトアニア</strong>のメーメルも併合したんだ。</p>\n<blockquote><p>ヒトラーの「最後」は「1938年では最後」って意味だった！ これまでも、国際的な約束を破り続けてきたんだから、ダマされた英仏も問題だよ</p></blockquote>\n<p>とどまるところを知らないヒトラーの野望は、ついに<strong class=\"source-bold\">ポーランド</strong>にも向かい、1939年3月には、</p>",
  "351": "<h2>351</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ドイツの侵略と第二次世界大戦の勃発</u></p>\n<p>ヴェルサイユ条約でドイツが失った<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド<ruby>回廊<rt>かいろう</rt></ruby></strong></span>での<strong class=\"source-bold\">鉄道と道路の建設権</strong>、さらには海港都市<strong class=\"source-bold\">ダンツィヒ</strong>の返還（第一次世界大戦までドイツ領だった）を要求した。この時、チェコスロヴァキア解体にショックを受けた<strong class=\"source-bold\">英仏</strong>が、宥和政策をやめて<strong class=\"source-bold\">ポーランドへの支援を約束</strong>したから、<strong class=\"source-bold\">ポーランドはドイツの要求を拒否</strong>したんだ。そして、英仏はソ連との連携を模索し始めたんだ。</p>\n<p>ただ、<strong class=\"source-bold\">スターリンは英仏を全く信用していない</strong>から、「ドイツとの関係を改善したほうが得だな」と考えてたんだ。だって同じ時期に、ソ連は<ruby>満洲<rt>まんしゅう</rt></ruby>で日本と軍事衝突しているからね。<strong class=\"source-bold\">ノモンハン事件</strong>だよ（<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.323</span>）！ 覚えてる？ <strong class=\"source-bold\">スターリンは日独の挟み撃ちを避けたかった</strong>んだね。そして<strong class=\"source-bold\">ヒトラー</strong>にとっても、ソ連との連携は魅力的だった。スターリンがウラで何を考えていようと、<strong class=\"source-bold\">英仏とソ連の挟み撃ちになるよりはマシ</strong>だよ。あとは、ムッソリーニが<ruby>怖気<rt>おじけ</rt></ruby>づいて裏切らないように、「バルカンを取っていいぞ！」っておだてておけば、敵は英仏だけになる。こうしてイタリアは<strong class=\"source-bold\">アルバニアを併合</strong>し、さらに英仏への<ruby>牽制<rt>けんせい</rt></ruby>として<strong class=\"source-bold\">ドイツ＝イタリア軍事同盟【鋼鉄同盟】</strong>を成立させた。</p>\n<p>そして1939年8月、世界中に衝撃が走った！。<strong class=\"source-bold\">ドイツとソ連が急接近</strong>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独ソ<ruby>不可侵<rt>ふかしん</rt></ruby>条約</strong></span>を結んだんだよ。よく考えてね。<strong class=\"source-bold\">ヒトラー</strong>はこれまで「<strong class=\"source-bold\">反ソ・反共</strong>」と言い続けてたし、<strong class=\"source-bold\">スターリン</strong>も「<strong class=\"source-bold\">反ファシズム</strong>」だと叫んで人民戦線をつくったじゃん。お互いを「世界一の<ruby>極悪人<rt>ごくあくにん</rt></ruby>」と<ruby>罵<rt>ののし</rt></ruby>り合ってたくせに、どっちも<ruby>独裁<rt>どくさい</rt></ruby>者だから考えてることは同じ。お互いが「最大の敵」なんだけど、単に「<strong class=\"source-bold\">今は戦いたくない</strong>」んだ。さらに両国は、この条約に付随する秘密議定書で<strong class=\"source-bold\">ポーランド</strong>や<strong class=\"source-bold\">バルト3国</strong>、<strong class=\"source-bold\">フィンランド</strong>などでの勢力範囲も決めた。もはや、<strong class=\"source-bold\">英仏はソ連と連携できない</strong>よ。</p>\n<blockquote><p>世界中がヒトラーとスターリンにダマされた！ もはや、世界大戦は避けられないよ……</p></blockquote>\n<p>そして一番ショックを受けたのは、<strong class=\"source-bold\">日独伊三国<ruby>防共<rt>ぼうきょう</rt></ruby>協定を結んでいた日本</strong>だよ。「ドイツとともにソ連を倒す」と思ってたのに、独ソが接近しちゃった……。日本の<ruby>平沼<rt>ひらぬま</rt></ruby><ruby>騏一郎<rt>きいちろう</rt></ruby>首相は「欧州の天地は複雑怪奇で対処できない」と大混乱し、首相を辞任してしまった。おそらく、リアルタイムで独ソ不可侵条約の意味がわかっていたのは、スターリンとヒトラーだけだよ。</p>\n<p>こうしてヒトラーは、<strong class=\"source-bold\">戦争の起こる可能性を英仏だけに絞れた</strong>けど、この時点で開戦するのは厳しかったんだよ。ただ、独裁者として挑発的で強気な発言を繰り返してきたから、今さら「英仏が強いから開戦しない」とも言えない。結局、英仏が動かないことを期待しつつ、<strong class=\"source-bold\">ヒトラーは</strong>「一か八かの賭け」で<strong class=\"source-bold\">ポーランド<ruby>侵攻<rt>しんこう</rt></ruby>に踏み切った</strong>んだよ。</p>\n<p>1939年9月、<strong class=\"source-bold\">ドイツ軍</strong>は空軍による爆撃と陸軍の戦車部隊を組み合わせた<strong class=\"source-bold\">電撃戦</strong>によって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランドに侵攻</strong></span>し、わずか3週間で制圧した。これに対し、<strong class=\"source-bold\">英仏</strong>は約束</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "352": "<h2>352</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<p>どおり<strong class=\"source-bold\">ドイツに<ruby>宣戦<rt>せんせん</rt></ruby>を<ruby>布告<rt>ふこく</rt></ruby></strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第二次世界大戦</strong></span>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>したよ。そして、ドイツ軍の攻撃が終わると、独ソ<ruby>不可侵<rt>ふかしん</rt></ruby>条約で密約を結んだ<strong class=\"source-bold\">ソ連</strong>も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランドに<ruby>侵攻<rt>しんこう</rt></ruby></strong></span>し、続けて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルト3国</strong></span>も占領すると、さらに11月には<strong class=\"source-bold\">フィンランドにも侵攻</strong>して、<strong class=\"source-bold\">カレリア地方を奪った</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連＝フィンランド戦争</strong></span> <strong class=\"source-bold\">【</strong>冬戦争<strong class=\"source-bold\">】</strong>）。これに対し、<strong class=\"source-bold\">国際連盟はソ連を除名</strong>したんだけど、もはや連盟にはなんの力もなかったんだよ。あっ！ 国際連盟を脱退した国は、日独伊を含めていっぱいあるけど、<strong class=\"source-bold\">除名された国はソ連しかない</strong>からね！ その後、ソ連は<strong class=\"source-bold\">バルト3国をソ連に編入</strong>（<ruby>併合<rt>へいごう</rt></ruby>）し、ルーマニアからは<strong class=\"source-bold\">ベッサラビア</strong>を奪ったほか、ポーランド人将校の虐殺事件（<strong class=\"source-bold\">カティンの森事件</strong>）なども起こしたよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">第二次世界大戦</strong></span></h3>\n<h3><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">◀ 「奇妙な戦争」から一転。ドイツは電撃戦で一気に西ヨーロッパを制圧！</strong></span></h3>\n<p>開戦前のドイツの戦争計画は、「英仏が動かないだろう……」って思ってつくられていたから、ドイツはまだ英仏と戦える状態ではなかった。一方の英仏も、「ドイツが攻めてきたら守ればいい」と思ってたんだ。こうして、どちらも相手を攻撃しなかったので、1939年中は「<strong class=\"source-bold\">奇妙な戦争</strong>」と呼ばれる<strong class=\"source-bold\">戦闘がない状態</strong>が続いたんだ。そしてこの間に、<strong class=\"source-bold\">ヒトラーは遅れていた軍備増強を急いだ</strong>。英仏が攻撃しなかったから、ヒトラーは<ruby>賭<rt>か</rt></ruby>けに勝っちゃったわけだ。</p>\n<blockquote><p>ヒトラーの暴走を止めるチャンスは何度もあったはずなのに止められず、ここでもヒトラーに時間を与えるなんて……</p></blockquote>\n<p>1940年に入り、軍備が整った<strong class=\"source-bold\">ドイツ軍は一気に攻勢に出た</strong>。4月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">デンマーク</strong></span>に侵攻し、そのまま<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ノルウェー</strong></span>に上陸して、両国を<ruby>占領<rt>せんりょう</rt></ruby>した。続けてヒトラーは<strong class=\"source-bold\">フランスへの侵攻</strong>を始めるんだけど、これまでの敵とはわけが違う。ヒトラーも「さすがにイギリス空軍とフランス陸軍が協力したら、フランスへの電撃戦は成功しないだろう……」と思っていた。しかもフランスは、第一次世界大戦の<ruby>塹壕<rt>ざんごう</rt></ruby>戦の経験から、ドイツとの国境に300km以上にもわたる巨大な地下<ruby>要塞<rt>ようさい</rt></ruby>（<strong class=\"source-bold\">マジノ線</strong>）を造っていたから、簡単には国境を突破できない。でもね、マジノ線はフランスとベルギーの国境には造られていなかったんだ。だって、<strong class=\"source-bold\">ベルギーは永世中立国</strong>なんだもん。しかし、ヒトラーは永世中立など無視！。フランス国境を突破すべく、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オランダ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルギー</strong></span>に攻め込んだ。<strong class=\"source-bold\">オランダはわずか5日で降伏</strong>し、ベルギーに侵入したドイツ軍は、英仏軍の防御が手薄なアルデンヌの森林地帯（ここにはマジノ線がない！）を戦車部隊で突破。これで<strong class=\"source-bold\">英仏軍は完全に孤立</strong>し、ドーヴァー海峡に面した<strong class=\"source-bold\">ダンケルク</strong>に包囲されてしまった。</p>\n<p>追い込まれたイギリスでは、ドイツに対する<ruby>宥和<rt>ゆうわ</rt></ruby>政策を進めた<strong class=\"source-bold\">チェンバレン政権に対する批判</strong>が高まり、かわって<strong class=\"source-bold\">ドイツへの徹底抗戦を主張</strong>していた保守党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャ</strong></span></p>",
  "353": "<h2>353</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第二次世界大戦</u></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ーチル</strong></span>が首相となり、<strong class=\"source-bold\">労働党も含めた戦時内閣</strong>を組閣した。でも、チャーチルが首相となって最初に命じたことは、屈辱的な<strong class=\"source-bold\">ダンケルクからの<ruby>撤退<rt>てったい</rt></ruby></strong>なんだ。これでドイツ軍をジャマするものは何もなくなったから、攻撃開始からわずか1カ月でドイツ軍は「無防備都市」となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリに入城</strong></span>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランスは降伏</strong></span>した。そして、ドイツの優勢が明らかになると、<strong class=\"source-bold\">ムッソリーニも英仏に宣戦</strong>を布告したよ。</p>\n<p>こうして<strong class=\"source-bold\">フランスの北側</strong>（約5分の3）<strong class=\"source-bold\">はドイツ軍が占領</strong>し、パリを失ったフランスは<strong class=\"source-bold\">中部のヴィシー</strong>に政府を設置し、<strong class=\"source-bold\">ペタン</strong><ruby>元帥<rt>げんすい</rt></ruby>を<ruby>首班<rt>しゅはん</rt></ruby>に<strong class=\"source-bold\">ドイツ軍に協力</strong>したんだ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィシー政府</strong></span>）。これに対し<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴール</strong></span>将軍は、海外領土を拠点にドイツ軍への抵抗を続けることを主張し、1940年6月、<strong class=\"source-bold\">ロンドンに<ruby>亡命<rt>ぼうめい</rt></ruby></strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由フランス政府</strong></span>をつくった。ド＝ゴールはロンドンからラジオで、ドイツ軍への抵抗（<strong class=\"source-bold\">レジスタンス</strong>）を呼びかけたんだ。</p>\n<blockquote><p>ペタンは、第一次世界大戦の時に、ヴェルダン要塞の攻防戦で活躍した英雄だよ</p></blockquote>\n<p>これで、ヨーロッパで<strong class=\"source-bold\">ドイツと戦っている国はイギリスだけ</strong>になった。チャーチルはひたすら「ドイツへの徹底抗戦」を呼びかけたものの、この時点で反撃するのはさすがにムリだ。対するヒトラーはイギリスに上陸する前に徹底的にイギリス人の戦意をなくすため、<strong class=\"source-bold\">ロンドンなどの大都市への爆撃</strong>をおこなった。このイギリス制空権をめぐる激しい戦い（<strong class=\"source-bold\">バトル・オブ・ブリテン</strong>）では、ドイツ空軍が何度も猛攻を仕掛けたものの、レーダーを発明したイギリス空軍が反撃してなんとか持ちこたえ、ドイツは最後まで制空権を奪うことができなかった。ヒトラーは、イギリスが途中で戦争続行を断念すると期待していたけど、チャーチルは決して屈せず、最終的には<strong class=\"source-bold\">ヒトラーのほうがイギリス本土への攻撃を<ruby>諦<rt>あきら</rt></ruby>めた</strong>んだ。そしてこの間、<strong class=\"source-bold\">チャーチル</strong>はアメリカのフランクリン＝ローズヴェルト大統領に、「とにかく参戦してくれ！」と訴えたけど、<strong class=\"source-bold\">アメリカ</strong>では「ヨーロッパには<ruby>介入<rt>かいにゅう</rt></ruby>しない」という<strong class=\"source-bold\">孤立主義が強く</strong>、<strong class=\"source-bold\">中立法</strong>があったために<strong class=\"source-bold\">ローズヴェルトは参戦も支援もできなかった</strong>んだ。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong> <span data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725;padding:0 0.2em\"><strong class=\"source-bold\">第二次世界大戦中のフランス</strong></span></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由フランス政府</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴール</strong></span>が<strong class=\"source-bold\">ロンドン</strong>でつくった亡命政権</p>\n<p><span data-source-marker=\"triangle\" data-source-color=\"gray\" style=\"color:#a6aaa0\">▶</span>ロンドンからラジオで<strong class=\"source-bold\">レジスタンス</strong>（ドイツ軍への抵抗）を呼びかける</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィシー政府</strong></span>……<strong class=\"source-bold\">ペタン</strong>を首班に<strong class=\"source-bold\">中部のヴィシー</strong>に成立した政府</p>\n<p><span data-source-marker=\"triangle\" data-source-color=\"gray\" style=\"color:#a6aaa0\">▶</span>降伏後、<strong class=\"source-bold\">ドイツ軍に協力</strong></p>\n<p><span data-source-marker=\"triangle\" data-source-color=\"gray\" style=\"color:#a6aaa0\">▶</span>フランス北部はドイツ軍が占領、南部をヴィシー政府が支配</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "354": "<h2>354</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ アジアでは日本が南進政策を開始して、日米対立が深まる！</strong></span></h3>\n<p>ここでアジアの状況を見ておこう。1937年から<strong class=\"source-bold\">日本と中国は全面戦争</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日中戦争</strong></span>）に突入していたけど、すでに日本は中国戦線で行き詰まっていた<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.322〜325</span>。そこに、<strong class=\"source-bold\">ヨーロッパ戦線でのドイツの快進撃</strong>が伝えられると、日本では「ドイツが勝利した勢いに乗って<strong class=\"source-bold\">東南アジアに進出</strong>し、石油などの資源を確保して、ヨーロッパ支配から解放された“<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>大東亜<rt>だいとうあ</rt></ruby><ruby>共栄圏<rt>きょうえいけん</rt></ruby></strong></span>”をつくる」という構想が生まれた。そして、1940年には日独伊三国<ruby>防共<rt>ぼうきょう</rt></ruby>協定を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日独伊三国同盟</strong></span>へと強化して、<strong class=\"source-bold\">ソ連以外に対しても連携する</strong>ことを明らかにしたんだ。</p>\n<p>さらに日本は、<strong class=\"source-bold\">フランスが降伏</strong>したのをきっかけに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス領インドシナ北部</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北部仏印</strong></span>】</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">に<ruby>進駐<rt>しんちゅう</rt></ruby></strong></span>して、<strong class=\"source-bold\">東南アジア進出（南進政策）</strong>の拠点をつくり、同時にインドシナから<ruby>雲南<rt>うんなん</rt></ruby>を経由した<ruby>蔣介石<rt>しょうかいせき</rt></ruby>への支援（<strong class=\"source-bold\"><ruby>援蔣<rt>えんしょう</rt></ruby>ルート</strong>）を断ち切ろうとしたんだ。でも、これが東南アジアに植民地を持つ各国との対立を引き起こした。だって、<strong class=\"source-bold\">マレー半島はイギリス領、インドネシアはオランダ領、そしてフィリピンはアメリカ領</strong>だ。のちに日本の、特に軍部は、この3国に<strong class=\"source-bold\">中国</strong>を加えた4国を「<strong class=\"source-bold\">ABCD包囲陣</strong>」と呼んで、「4国で日本を包囲し、圧迫している」と主張したんだけど（AはAmerica《アメリカ》、BはBritain《イギリス》、CはChina《中国》、DはDutch《オランダ》）、<strong class=\"source-bold\">日米の対立</strong>が深まるにつれてアメリカは<strong class=\"source-bold\">石油の輸出制限</strong>などを強めたんだ。こうなると、石油や鉄などの多くをアメリカから輸入していた日本は、戦略物資が確保できなくなる。だから、日本の軍部は「石油がなくなる前に、早く開戦すべきだ！ 油田のある東南アジアに<ruby>侵略<rt>しんりゃく</rt></ruby>しろ！」と主張し始めた。中国戦線は終結の糸口さえ見えないのに、戦線を拡大してどうすんだよ……。</p>\n<p>そして1941年、日本はソ連との間で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日ソ中立条約</strong></span>を結んだ。これは、北方のソ連と相互不侵略を約束して<strong class=\"source-bold\">南進政策を進めるため</strong>だ。でも、こんな条約を結んだら、「オマエ、もっと東南アジアに侵略しようとしてるだろ」って思われて、<strong class=\"source-bold\">アメリカとの対立がさらにひどくなる</strong>。このあと、<strong class=\"source-bold\"><ruby>近衛<rt>このえ</rt></ruby>内閣</strong>が<strong class=\"source-bold\">日米交渉</strong>を始めたんだけど、交渉中に日本が<strong class=\"source-bold\">フランス領インドシナ南部に進駐</strong>したから、アメリカは日本に対する<strong class=\"source-bold\">石油の全面禁輸</strong>を決めるなど、ますます態度を硬化させた。もはや外交的な解決は不可能だよ。こうして<strong class=\"source-bold\">近衛首相は辞任</strong>し、陸軍大臣だった<ruby>東条英機<rt>とうじょうひでき</rt></ruby>が首相になった。そしてアメリカが、中国やインドシナからの全面撤退と三国同盟からの脱退を要求する「<strong class=\"source-bold\">ハル＝ノート</strong>」を日本に提示し、「もはや交渉できない！」と考えた日本は、<strong class=\"source-bold\">日米開戦へと向かっていく</strong>んだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ヨーロッパではついに戦線が拡大。ドイツがソ連と開戦した！</strong></span></h3>\n<p>ヨーロッパでイギリスだけがドイツと戦うなかで、1941年3月、<strong class=\"source-bold\">アメリカ</strong>では中立法が改正され<strong class=\"source-bold\"><ruby>武器貸与法<rt>ぶきたいよほう</rt></ruby></strong>が成立したよ。ローズヴェルト大統領は、これまでずっと「イギリスを支援するための法律制定」を議会に訴えていたからね。武器貸与法の成立によって、大統領の権限で<strong class=\"source-bold\">軍需品の売却、貸与、譲渡</strong>などができるようになったんだ。</p>",
  "355": "<h2>355</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第二次世界大戦</u></p>\n<h4><strong class=\"source-bold\">〈第二次世界大戦（ヨーロッパ）〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><strong class=\"source-bold\">ノルウェー</strong></td></tr><tr><td><strong class=\"source-bold\">スウェーデン</strong></td></tr><tr><td><strong class=\"source-bold\">フィンランド</strong></td></tr><tr><td><strong class=\"source-bold\">エストニア</strong></td></tr><tr><td><strong class=\"source-bold\">ラトヴィア</strong></td></tr><tr><td><strong class=\"source-bold\">リトアニア</strong></td></tr><tr><td><strong class=\"source-bold\">アイルランド</strong></td></tr><tr><td><strong class=\"source-bold\">イギリス</strong></td></tr><tr><td>ロンドン <span data-source-marker=\"dot\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td></tr><tr><td><strong class=\"source-bold\">デンマーク</strong></td></tr><tr><td><strong class=\"source-bold\">オランダ</strong></td></tr><tr><td><strong class=\"source-bold\">ベルギー</strong></td></tr><tr><td><strong class=\"source-bold\">フランス</strong></td></tr><tr><td>パリ <span data-source-marker=\"dot\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td></tr><tr><td><strong class=\"source-bold\">ドイツ</strong></td></tr><tr><td><strong class=\"source-bold\">ベルリン</strong> <span data-source-marker=\"dot\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td></tr><tr><td>（<strong class=\"source-bold\">ポーランド</strong>）</td></tr><tr><td><strong class=\"source-bold\">ソ連</strong></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">モスクワ</span> <span data-source-marker=\"dot\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td></tr><tr><td><strong class=\"source-bold\">スイス</strong></td></tr><tr><td><strong class=\"source-bold\">ハンガリー</strong></td></tr><tr><td><strong class=\"source-bold\">ルーマニア</strong></td></tr><tr><td><strong class=\"source-bold\">ユーゴスラヴィア</strong></td></tr><tr><td><strong class=\"source-bold\">ブルガリア</strong></td></tr><tr><td><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td><strong class=\"source-bold\">イタリア</strong></td></tr><tr><td><strong class=\"source-bold\">ポルトガル</strong></td></tr><tr><td><strong class=\"source-bold\">スペイン</strong></td></tr><tr><td><strong class=\"source-bold\">トルコ</strong></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ダンケルク</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ノルマンディー上陸</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ポーランド侵攻</span> <span data-source-marker=\"curved-arrow\" data-source-color=\"black\" style=\"color:#111111\">↷</span> <span data-source-marker=\"curved-arrow\" data-source-color=\"black\" style=\"color:#111111\">⤴</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">スターリングラードの戦い</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ヴィシー政府</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">シチリア上陸</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #111111;padding:0 0.2em\">枢軸国の最大勢力範囲</span> <span data-source-marker=\"boundary-band\" data-source-color=\"red\" style=\"color:#ed655a\">━</span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"red\" style=\"color:#ed655a\">■</span><span data-source-marker=\"area\" data-source-pattern=\"vertical-lines\" data-source-color=\"red\" style=\"color:#ed655a\">▥</span> 枢軸国</td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"green\" style=\"color:#859476\">■</span> 中立国</td></tr><tr><td>※上記以外は連合国</td></tr></tbody></table></div>\n<p>一方、イギリス上陸を<ruby>諦<rt>あきら</rt></ruby>めた<strong class=\"source-bold\">ドイツ軍</strong>の標的は、<strong class=\"source-bold\">バルカン半島</strong>へと変わっていた。当時、ソ連が東欧に勢力圏を拡大しようとしていたのに対抗して、ドイツ軍は<strong class=\"source-bold\">ルーマニア、ブルガリア、ユーゴスラヴィア</strong>、さらにはイタリアを助けて<strong class=\"source-bold\">ギリシア</strong>にも進出したんだ。ドイツの動きを警戒した<strong class=\"source-bold\">スターリン</strong>は、東方で日本との戦闘を起こさないために、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日ソ中立条約</strong></span>を結んだんだけど、ヒトラーは着々とソ連に攻め込む準備を始めている。独ソ開戦が近いと考えたチャーチルは、「自分は反共産党主義者だが、ナチスを打倒するためにはソ連への援助も惜しまない！」とラジオで演説したよ。「敵の敵は味方」というチャーチルの現実路線だ。</p>\n<p>1941年6月、ついに<strong class=\"source-bold\">ドイツ</strong>は独ソ<ruby>不可侵<rt>ふかしん</rt></ruby>条約を<ruby>破棄<rt>はき</rt></ruby>して<strong class=\"source-bold\">ソ連に攻撃を開始</strong>し、<ruby>宣戦布告<rt>せんせんふこく</rt></ruby>した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独ソ戦</strong></span>）。ドイツ軍は北部では<strong class=\"source-bold\">レニングラード</strong>（もともとのペトログラード。レーニン死後の1924年に改称）近郊まで攻め込んで包囲し、11月には<strong class=\"source-bold\">モスクワ近郊</strong>まで一気に到達したよ。対するソ連軍は……とりあえず逃げる。てか、ソ連の「とりあえず逃げる」は、いざとなったらシベリアまで1万キロ逃げれるからね！。ナポレオンのロシア遠征と同じだよ。ロシアの冬はマイナス20℃とかになるから、ドイツ人は<ruby>凍<rt>こご</rt></ruby>え死ぬに違いない。実際、冬になるとあまりの寒さにドイツ軍の攻撃は中断され、12月には<strong class=\"source-bold\">ソ連軍が反抗を開始</strong>したよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "356": "<h2>356</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<p>戦局の転換を受けて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランクリン＝ローズヴェルト</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャーチル</strong></span>は、ニューファンドランド沖の大西洋で<strong class=\"source-bold\">米英首脳会談</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大西洋上会談</strong></span>）をおこない、この戦争を、民主主義を守るためにナチスの暴政を倒す「<strong class=\"source-bold\">反ファシズムの戦い</strong>」であることを確認するとともに、<strong class=\"source-bold\">民族<ruby>自決<rt>じけつ</rt></ruby>や国際平和機構の再建</strong>などを内容とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大西洋<ruby>憲章<rt>けんしょう</rt></ruby></strong></span>を発表したよ。これはソ連を含めた多くの国から支持され、<strong class=\"source-bold\">連合国が形成される前提</strong>となったんだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 日本もアメリカと開戦し、わずか半年で東南アジアを制圧！</strong></span></h3>\n<p>一方で、<strong class=\"source-bold\">アメリカとの交渉が決裂した日本</strong>は、「勝てる見込みはないが、とにかく<ruby>緒戦<rt>しょせん</rt></ruby>でアメリカの太平洋艦隊を壊滅させ、引き分けに持ち込む」という、全く無謀な戦争に突入することを決めた。こうして1941年12月8日、日本海軍の戦闘機部隊が<strong class=\"source-bold\">ハワイのアメリカ太平洋艦隊に奇襲攻撃</strong>を仕掛け（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>真珠湾<rt>しんじゅわん</rt></ruby>奇襲</strong></span>）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">太平洋戦争</strong></span>が始まった。日本にそこまでの軍備がないと思っていたローズヴェルトは、反撃の機会を逃した。ただ、奇襲の成功を見た<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ・イタリアがアメリカに<ruby>宣戦<rt>せんせん</rt></ruby></strong></span>したから、イギリスを支援して<strong class=\"source-bold\">アメリカが参戦</strong>することになった。しかも、真珠湾奇襲に衝撃を受けたアメリカ国民は、一気に戦争に向かって結束したんだよ。</p>\n<p>ただ、ハワイの太平洋艦隊が壊滅したから、アメリカは開戦直後に西海岸や大西洋から太平洋へと海軍を移動しなきゃいけなくなった。この半年の間に、日本は<strong class=\"source-bold\"><ruby>香港<rt>ホンコン</rt></ruby></strong>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マレー</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シンガポール</strong></span>・<strong class=\"source-bold\">ビルマ</strong>（英領）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジャワ</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スマトラ</strong></span>（蘭領）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フィリピン</strong></span>（米領）を占領し、1942年半ばまでに<strong class=\"source-bold\">タイを除く東南アジア全域を制圧</strong>したよ。<strong class=\"source-bold\">タイは日本側で参戦</strong>したから、<ruby>占領<rt>せんりょう</rt></ruby>する必要はない。これでインドやオーストラリアを孤立させて、イギリスに打撃を与えるつもりだったんだ（地図<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.360</span>）。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong> <span data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725;padding:0 0.2em\"><strong class=\"source-bold\">第二次世界大戦のポイント</strong></span></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>ヨーロッパ</p>\n<p><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>開戦……ドイツ軍の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド<ruby>侵攻<rt>しんこう</rt></ruby></strong></span>［1939.9］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>イギリス・フランスがドイツに宣戦</p>\n<p><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>戦局の拡大……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独ソ戦</strong></span>の開始［<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1941</strong></span></u>.6］</p>\n<p><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>戦局の転換……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリングラードの戦い</strong></span>［<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1942</strong></span></u>.8〜43.2］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>ドイツ軍の敗色が濃厚となる</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span>アジア・太平洋</p>\n<p><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>開戦……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>盧溝橋<rt>ろこうきょう</rt></ruby>事件</strong></span>［1937］以降、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日中戦争</strong></span>に突入</p>\n<p><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>戦局の拡大……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">真珠湾奇襲</strong></span>［<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1941</strong></span></u>.12］＝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日米開戦</strong></span></p>\n<p><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>戦局の転換……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミッドウェー海戦</strong></span>［<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1942</strong></span></u>.6］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>日本軍が<ruby>制空権<rt>せいくうけん</rt></ruby>・<ruby>制海権<rt>せいかいけん</rt></ruby>を失う</p></blockquote>\n<blockquote><p>第二次世界大戦は、1941、42年に注目！</p></blockquote>",
  "357": "<h2>357</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第二次世界大戦</u></p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ミッドウェー海戦とスターリングラード……日本とドイツの勢いが止まる！</strong></span></h3>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独ソ戦</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日米開戦</strong></span>、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ・イタリアの対米宣戦</strong></span>で、<strong class=\"source-bold\">ヨーロッパとアジアの戦争は1つの大きな戦争になった</strong>。日独伊を中心とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>枢軸国<rt>すうじくこく</rt></ruby></strong></span>と戦う<strong class=\"source-bold\">米・英・ソ連・中国</strong>など<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">連合国</strong></span>26カ国は、<strong class=\"source-bold\">連合国共同宣言</strong>を発表し、「自由と民主主義を守ること」を戦争目的として、<strong class=\"source-bold\">単独で<ruby>講和<rt>こうわ</rt></ruby>を結ばない</strong>ことを約束した。同時に、4番目に署名した中国が4大国の地位を得ることになった。そして、1942年には第二次世界大戦の戦局を大きく変える2つの戦いが起きたんだ。</p>\n<p>真珠湾奇襲ののち、東南アジアから西太平洋を制圧した日本に対し、<strong class=\"source-bold\">アメリカ軍の反撃</strong>が始まったよ。1942年6月、中部太平洋のアメリカ領ミッドウェー島を攻略しようとした日本海軍はアメリカ海軍の猛攻を受け、主力空母4隻と戦闘機300機を失って惨敗した。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミッドウェー海戦</strong></span>で<strong class=\"source-bold\">日本は制空権と制海権をアメリカに奪</strong>われ、直後にソロモン諸島の<strong class=\"source-bold\">ガダルカナル島</strong>でも敗退、以後アメリカ軍の猛反撃を受けることになるんだ（地図<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.360</span>）。</p>\n<p>一方、<strong class=\"source-bold\">ヒトラー</strong>は1942年のうちにソ連との戦争に決着をつけるため、ヴォルガ川流域の重要拠点<strong class=\"source-bold\">スターリングラード</strong>とロシア南東部の<ruby>油田<rt>ゆでん</rt></ruby>地帯の占領を目指して、<strong class=\"source-bold\">ソ連に猛攻</strong>を仕掛けたんだ。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリングラードの戦い</strong></span>でヒトラーはドイツ軍に撤退を禁じ、スターリンも人海戦術で対抗したから、とんでもない大激戦になった。スターリンは「冬になれば反撃できるから、とにかく冬まで持ちこたえろ！」と言って次々と兵士を送り込んだよ。<strong class=\"source-bold\">第二次世界大戦の死者数がソ連だけとびぬけて多い</strong>のは（2000万人以上だ！）、この時の人海戦術も原因の1つだね。そして冬まで持ちこたえたソ連軍が反撃を開始し、<strong class=\"source-bold\">ドイツ軍は壊滅</strong>した。スターリンは米英との協力体制を確実にするために、<strong class=\"source-bold\">コミンテルンを解散</strong>したんだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 日本・ドイツの敗色が濃くなり、連合軍が反撃開始！</strong></span></h3>\n<p>1943年になると日本とドイツの敗色が濃くなり、勝利の見通しが開けてきた連合国はいよいよ反撃の作戦を考え始めた。1月には<strong class=\"source-bold\">ローズヴェルト</strong>と<strong class=\"source-bold\">チャーチル</strong>がモロッコの<strong class=\"source-bold\">カサブランカで会談</strong>し、最初の目標としてシチリア島に侵攻して<strong class=\"source-bold\">イタリアを総攻撃</strong>することを決めた。こうして7月に米英軍が<strong class=\"source-bold\">シチリア島に上陸</strong>すると、すでに戦意を失っていたイタリア軍は総崩れとなり、国王派とファシスト党内の反ムッソリーニ派が手を組んで<strong class=\"source-bold\">ムッソリーニを失脚</strong>させ、反ムッソリーニ派の<strong class=\"source-bold\">バドリオ</strong>将軍が政権に<ruby>就<rt>つ</rt></ruby>いた。そして9月に<strong class=\"source-bold\">バドリオによるイタリア新政府は無条件降伏</strong>するんだけど、降伏後は<strong class=\"source-bold\">ドイツに宣戦</strong>することになるよ。ちなみにムッソリーニはドイツ軍に救出されたんだけど、結局捕まって銃殺されちゃった……。</p>\n<p>イタリアが降伏すると、連合国は<strong class=\"source-bold\">日本とドイツへの作戦</strong>を決めるために首脳会談をやったよ。まずは、<strong class=\"source-bold\">対日戦</strong>の基本方針を確認するため、<strong class=\"source-bold\">ローズヴェルト</strong>と<strong class=\"source-bold\">チャーチル</strong>は、中国の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>蔣介石<rt>しょうかいせき</rt></ruby></strong></span>とエジプトのカイロで会談した。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カイロ会談</strong></span>で発表された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カイロ宣言</strong></span>では、日本が<ruby>日清<rt>にっしん</rt></ruby>戦争以降に奪った領土（<strong class=\"source-bold\"><ruby>満洲<rt>まんしゅう</rt></ruby>、台湾、<ruby>澎湖<rt>ほうこ</rt></ruby>諸島</strong>）をすべて<strong class=\"source-bold\">中国に返還</strong>すること、<strong class=\"source-bold\">朝鮮は独立</strong>させることなどが決まったんだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "358": "<h2>358</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<p>そしてカイロ会談のあとすぐに、<strong class=\"source-bold\">ローズヴェルト</strong>と<strong class=\"source-bold\">チャーチル</strong>はイランの首都テヘランに飛び、<strong class=\"source-bold\">スターリン</strong>も含めた米英ソ首脳会談をおこなった。<strong class=\"source-bold\">米英ソ3大国の首脳が揃ったのはこれが最初</strong>だ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">テヘラン会談</strong></span>ではドイツに対する「<strong class=\"source-bold\">第二戦線</strong>」の問題を話し合った。これは、1941年以来激戦が続いていた独ソ戦（「第一戦線」）に加えて、米英軍がフランスに上陸して2つ目の戦線をつくり、ドイツを挟み撃ちにするってことだ。実は3国が考えてることは微妙に違って、スターリンは「とにかく早くしろ！」と言ったんだけど、チャーチルはイギリス軍の損害を少なくするために、なるべく時期を遅らせたい。で、ローズヴェルトはドイツを早いとこ片づけて、太平洋での日本との戦いに集中したい。最終的には、ローズヴェルトがチャーチルを説得して、1944年5月に実行することに決まったんだ。そしてこの時、ドイツ降伏後に<strong class=\"source-bold\">ソ連が対日参戦</strong>することが議題に上ったよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 連合軍がノルマンディーに上陸！ ドイツ軍は総崩れになった</strong></span></h3>\n<p>1944年6月、テヘラン会談での合意に基づいて、アメリカの<strong class=\"source-bold\">アイゼンハワー</strong>を最高司令官とする<strong class=\"source-bold\">米英軍が北フランスに上陸</strong>した。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ノルマンディー上陸作戦</strong></span>は「<strong class=\"source-bold\">史上最大の作戦</strong>」といわれ、米英軍は艦艇5300隻、飛行機1万4000機という圧倒的な戦力でドイツ軍を圧倒し、これにあわせてフランス各地で<strong class=\"source-bold\">レジスタンス</strong>（民衆によるドイツ軍への抵抗）が<ruby>蜂起<rt>ほうき</rt></ruby>！ フランス人の逆襲だよ。そして8月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリが解放</strong></span>されて、自由フランス政府の中心だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴール</strong></span>将軍がパリに戻ってきて<strong class=\"source-bold\">臨時政府を組織</strong>した。東からは、ノルマンディー上陸作戦にあわせて<strong class=\"source-bold\">ソ連軍も反撃を開始</strong>したから、ドイツ軍は総崩れになった。こののち、ドイツの各都市はアメリカ空軍も加わった連合軍に激しい<ruby>空襲<rt>くうしゅう</rt></ruby>を受け、特に東部ドイツの都市<strong class=\"source-bold\">ドレスデン</strong>は大空襲で徹底的に破壊されたんだよ。</p>\n<p>こうしてドイツの降伏が目前に迫った1945年2月、クリミア半島のヤルタで、<strong class=\"source-bold\">米英ソの3大国</strong>が<strong class=\"source-bold\">ドイツ降伏後の諸問題</strong>を話し合ったよ。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヤルタ会談</strong></span>ではポーランドとバルカン半島の問題でチャーチルとスターリンが対立するなど、すでに戦後の世界秩序をめぐる駆け引きが激しくなった。だって、スターリンは「ここまで3年も単独でドイツと戦ったのはソ連だろ！」と思ってるし、チャーチルはもともと反共産主義者だからね。そして、戦後のドイツについては、<strong class=\"source-bold\">無条件降伏</strong>と終戦後にドイツを<strong class=\"source-bold\">4大国（米英仏ソ）が分割占領</strong>すること、ドイツの<strong class=\"source-bold\">非武装化と戦争指導者の裁判</strong>などが決まったんだ。さらに<strong class=\"source-bold\">米ソの密約</strong>で、<strong class=\"source-bold\">ドイツ降伏後3カ月以内にソ連が対日参戦</strong>し、見返りに<strong class=\"source-bold\">南<ruby>樺太<rt>からふと</rt></ruby>・<ruby>千島<rt>ちしま</rt></ruby>全島をソ連領</strong>とすることが決められた。ただ、病気をおして会談に出席した<strong class=\"source-bold\">ローズヴェルトは会談後に急死</strong>してしまい、副大統領だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルーマン</strong></span>がアメリカ大統領になったよ。</p>\n<blockquote><p>ヤルタ会談は、広い意味では「<ruby>冷戦<rt>れいせん</rt></ruby>の開始」ともいわれるよ</p></blockquote>",
  "359": "<h2>359</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第二次世界大戦</u></p>\n<p>そして4月末に<strong class=\"source-bold\">ソ連軍</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリンに突入</strong></span>して総統官邸に接近したため、<strong class=\"source-bold\">ヒトラーは自殺</strong>、5月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツが無条件降伏</strong></span>して、ヨーロッパでの戦争は終わったんだ。</p>\n<h4><strong class=\"source-bold\">〈第二次世界大戦中の連合国の首脳会談〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><span data-source-background=\"gray\" style=\"background-color:#d7dad1\">会談名</span></td><td><span data-source-background=\"gray\" style=\"background-color:#d7dad1\">出席者</span></td><td><span data-source-background=\"gray\" style=\"background-color:#d7dad1\">内容</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大西洋上会談</strong></span><br>［1941.8］</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">F＝ローズヴェルト</strong></span>（米）<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャーチル</strong></span>（英）</td><td><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>戦争目的を「民主主義を守るため（<strong class=\"source-bold\">反ファシズム</strong>）」であると確認<br><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大西洋<ruby>憲章<rt>けんしょう</rt></ruby></strong></span>［1941.8］<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>領土不拡大、領土不変更、<strong class=\"source-bold\">民族<ruby>自決<rt>じけつ</rt></ruby></strong>、貿易の自由、労働と社会保障、海洋の自由、軍備縮小、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際平和機構の再建</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連合</strong></span>）を表明</td></tr><tr><td><strong class=\"source-bold\">カサブランカ会談</strong>［1943.1］</td><td><strong class=\"source-bold\">F＝ローズヴェルト</strong>（米）<br><strong class=\"source-bold\">チャーチル</strong>（英）</td><td><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>対<ruby>枢軸国<rt>すうじくこく</rt></ruby>（ドイツ・日本・イタリア）“<strong class=\"source-bold\">無条件降伏</strong>”<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>北アフリカでの反抗作戦の協議（<strong class=\"source-bold\">シチリア上陸</strong>）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カイロ会談</strong></span><br>［1943.11］</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">F＝ローズヴェルト</strong></span>（米）<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャーチル</strong></span>（英）<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>蔣介石<rt>しょうかいせき</rt></ruby></strong></span>（中）</td><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カイロ宣言</strong></span>［1943.11］……対日戦の基本方針<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>中国に<strong class=\"source-bold\"><ruby>満洲<rt>まんしゅう</rt></ruby>、台湾、<ruby>澎湖<rt>ほうこ</rt></ruby>諸島</strong>を返還<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span><strong class=\"source-bold\">朝鮮を独立</strong>させる<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>1914年以降に獲得した太平洋上の島の<ruby>放棄<rt>ほうき</rt></ruby></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">テヘラン会談</strong></span><br>［1943.11〜12］</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">F＝ローズヴェルト</strong></span>（米）<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャーチル</strong></span>（英）<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン</strong></span>（ソ）</td><td><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>ドイツに対する「<strong class=\"source-bold\">第二戦線</strong>」問題について協議<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>米英が1944年5月に実行することを約束<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>ドイツ降伏後の<strong class=\"source-bold\">ソ連の対日参戦</strong>も話し合う</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヤルタ会談</strong></span><br>［1945.2］</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">F＝ローズヴェルト</strong></span>（米）<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャーチル</strong></span>（英）<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン</strong></span>（ソ）</td><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヤルタ協定</strong></span>［1945.2］……ドイツの戦後処理<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span><strong class=\"source-bold\">無条件降伏</strong>、敗戦後は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米英仏ソ</strong></span>4カ国が<strong class=\"source-bold\">共同管理</strong><br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>非武装化と<ruby>戦犯<rt>せんぱん</rt></ruby>の裁判<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>ポーランドとユーゴの新政権樹立<br>※<strong class=\"source-bold\">ドイツ降伏後3カ月以内にソ連が対日参戦</strong>（米ソ密約）<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>見返りに<strong class=\"source-bold\">南樺太・千島全島</strong>をソ連が取得</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポツダム会談</strong></span><br>［1945.7〜8］</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルーマン</strong></span>（米）<br><strong class=\"source-bold\">チャーチル</strong><br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アトリー</strong></span>（英）<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン</strong></span>（ソ）</td><td><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span><strong class=\"source-bold\">ポツダム協定</strong>……ドイツの戦後処理の最終確認<br><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポツダム宣言</strong></span>［1945.7］……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米英中</strong></span>の3国の共同宣言<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>8月8日にソ連が参加<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>日本の<strong class=\"source-bold\">無条件降伏</strong><br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>日本の領土を<strong class=\"source-bold\">本土4島</strong>と周辺の小<ruby>島嶼<rt>とうしょ</rt></ruby>に限定<br><span data-source-marker=\"dot\" data-source-color=\"green\" style=\"color:#859476\">●</span>戦後の連合国占領、戦犯の裁判と民主化</td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "360": "<h2>360</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第19回</strong></span> 第二次世界大戦</p>\n<h4><strong class=\"source-bold\">〈太平洋戦争〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><strong class=\"source-bold\">モンゴル人民共和国</strong></td></tr><tr><td>「<strong class=\"source-bold\">満洲国</strong>」</td></tr><tr><td><strong class=\"source-bold\">朝鮮</strong></td></tr><tr><td><strong class=\"source-bold\">中華民国</strong></td></tr><tr><td><strong class=\"source-bold\">日本</strong></td></tr><tr><td>重慶 <span data-source-marker=\"dot\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td></tr><tr><td>南京 <span data-source-marker=\"dot\" data-source-color=\"red\" style=\"color:#e52715\">●</span></td></tr><tr><td><strong class=\"source-bold\">インド</strong>（英）</td></tr><tr><td><strong class=\"source-bold\">ビルマ</strong>（英）</td></tr><tr><td><strong class=\"source-bold\">タイ</strong></td></tr><tr><td><strong class=\"source-bold\">フランス領<br>インドシナ</strong></td></tr><tr><td><strong class=\"source-bold\">フィリピン</strong>（米）</td></tr><tr><td><strong class=\"source-bold\">オランダ領東インド</strong></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ソ連 対日参戦</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">米軍 沖縄上陸</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">硫黄島</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">サイパン島陥落</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">レイテ沖海戦</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ミッドウェー海戦</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">真珠湾奇襲</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ガダルカナル島撤退</span> <span data-source-marker=\"cross\" data-source-color=\"red\" style=\"color:#e52715\">×</span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td></tr><tr><td><span data-source-marker=\"area\" data-source-color=\"pink\" style=\"color:#f0a0a0\">■</span> 枢軸国</td></tr><tr><td><span data-source-marker=\"boundary-band\" data-source-color=\"red\" style=\"color:#e52715\">━</span> 日本軍の最大勢力範囲</td></tr><tr><td><span data-source-marker=\"arrow\" data-source-color=\"green\" style=\"color:#315837\">➡</span> 対日参戦後のソ連軍の侵攻</td></tr><tr><td><span data-source-marker=\"arrow\" data-source-color=\"brown\" style=\"color:#a43725\">➡</span> 連合軍（おもに米軍）の反撃</td></tr></tbody></table></div>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 島々を奪い合う死闘、沖縄戦、<ruby>原爆<rt>げんばく</rt></ruby>投下、ソ連の参戦……ついに日本も降伏した</strong></span></h3>\n<p>話をちょっとだけ戻して、<strong class=\"source-bold\">アジア・太平洋戦線</strong>について見ていこう。1944年6月に<strong class=\"source-bold\">サイパン島が<ruby>陥落<rt>かんらく</rt></ruby></strong>すると、アメリカ空軍による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日本の本土<ruby>空襲<rt>くうしゅう</rt></ruby></strong></span>が本格化して、日本の主要都市は壊滅的な被害を受けたよ。例えば、1945年3月の<strong class=\"source-bold\">東京大空襲</strong>では、東京の下町が焼け野原となり、10万人以上が死亡した。なんとか戦局を挽回しようと、日本海軍はフィリピン防衛のために主力艦隊を投入したんだけど、アメリカ海軍の圧倒的な兵力の前に<strong class=\"source-bold\">レイテ沖海戦</strong>で壊滅し、<strong class=\"source-bold\">レイテ島</strong>、さらにルソン島を奪われて<strong class=\"source-bold\">フィリピンから撤退</strong>したんだ。</p>\n<p>1945年に入るとアメリカ軍の反撃は激しさを増し、3月には<strong class=\"source-bold\"><ruby>硫黄<rt>いおう</rt></ruby>島</strong>を占領すると、4月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">沖縄本島に上陸</strong></span>した。沖縄戦は、大戦中の旧来の<strong class=\"source-bold\">日本領内におけるほぼ唯一の地上戦</strong>だ。この戦闘には沖縄の人たちが多数動員され、さらに米軍の<ruby>捕虜<rt>ほりょ</rt></ruby>にならないようにと集団<ruby>自決<rt>じけつ</rt></ruby>を命じられた住民もいたから、<strong class=\"source-bold\">軍人よりも民間人の犠牲者が多い</strong>んだよ。そして6月に沖縄の日本軍は全滅した。5月には、ヨーロッパでドイツが降伏していたから、もはや戦争を続けているのは日本だけになった。</p>\n<p>日本の敗戦が時間の問題になった7月、<strong class=\"source-bold\">ベルリン郊外</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポツダム</strong></span>で会談が開かれた。ここは参加者に注意しよう！ ローズヴェルトが病死したから、アメリカ大統領は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルーマン</strong></span>だ。そしてイギリスは当初<strong class=\"source-bold\">チャーチル</strong>が首相として出席したものの、会談中に<strong class=\"source-bold\">総選挙での保守党の敗北</strong>が決まると、途中から<strong class=\"source-bold\">労働党</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アトリー</strong></span>新首相がイギリスの代表になった。ソ連は<strong class=\"source-bold\">スターリン</strong>だけどさ。この会談では<strong class=\"source-bold\">ドイツの戦後処理を最終確認</strong>したんだけど、すでに米英とソ連の隔たりは大きかっ</p>",
  "361": "<h2>361</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第二次世界大戦</u></p>\n<p>た。そして<strong class=\"source-bold\">日本に対して無条件降伏を要求</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポツダム宣言</strong></span>が発表されたよ。あっ、この時点ではソ連は対日参戦していないから、ポツダム宣言は<strong class=\"source-bold\">米英と中国の共同宣言</strong>だからね（ソ連の参加は8月8日）。</p>\n<p>しかし日本では、軍部が「本土決戦で、日本人の最後の1人まで戦う！」と主張して降伏を受け入れなかったから、アメリカは開発したばかりの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">原子爆弾</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">原爆</strong></span>】</strong>を、<strong class=\"source-bold\">8月6日</strong>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">広島</strong></span>に投下した。原爆を使った理由の1つに、<strong class=\"source-bold\">アメリカがソ連に対する優位を示す</strong>という面があったんだ。これを見た<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連は対日参戦</strong></span>の日程を早め、8月8日に日本に<ruby>宣戦<rt>せんせん</rt></ruby>し、<strong class=\"source-bold\"><ruby>満洲<rt>まんしゅう</rt></ruby>・<ruby>樺太<rt>からふと</rt></ruby>・朝鮮</strong>へと侵入した。こうして満洲の日本軍も総崩れとなって日本は降伏に向かったんだけど、降伏の受諾をめぐって政府内が<ruby>揉<rt>も</rt></ruby>めていた<strong class=\"source-bold\">8月9日</strong>に、アメリカが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">長崎</strong></span>に2発目の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">原爆投下</strong></span>をおこなったんだよ。もし、ポツダム宣言が発表されてすぐに降伏していたら、広島・長崎への原爆投下はなかったと考えると、やりきれない気持ちになるよ……。そして、8月14日に昭和天皇の判断（“<ruby>聖断<rt>せいだん</rt></ruby>”）という形で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポツダム宣言の受諾</strong></span>を連合国に通告し、<strong class=\"source-bold\">8月15日</strong>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦争終結</strong></span><strong class=\"source-bold\">を国民に知らせる昭和天皇の<ruby>玉音<rt>ぎょくおん</rt></ruby>放送</strong>がおこなわれ、9月2日に東京湾に入港した戦艦ミズーリ号の甲板で降伏文書に調印した。こうして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日本は無条件降伏</strong></span>し、文字通りの世界大戦が終わったんだ。</p>\n<blockquote><p>日本は戦争での唯一の<ruby>被爆<rt>ひばく</rt></ruby>国として、核軍縮についてもっと考えてもいいと思うよ</p></blockquote>\n<p>さて、これで第二次世界大戦はおしまい。最後に年号check！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">!!</span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">年号のツボ</span></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ドイツの再軍備宣言</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1935</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>戦<rt>193</rt></ruby><ruby>こ<rt>5</rt></ruby></strong></span>れから 再軍備）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">スペイン内戦</strong>［19<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">36</strong></span>］（英仏が <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>見<rt>3</rt></ruby><ruby>向<rt>6</rt></ruby></strong></span>きもしない スペインに）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ミュンヘン会談</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1938</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>戦<rt>193</rt></ruby><ruby>や<rt>8</rt></ruby></strong></span>らずに <ruby>宥和<rt>ゆうわ</rt></ruby>政策）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">第二次世界大戦<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1939</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>得<rt>19</rt></ruby><ruby>策<rt>39</rt></ruby></strong></span>もなく 大戦勃発）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>真珠湾<rt>しんじゅわん</rt></ruby>奇襲（太平洋戦争勃発）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1941</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>よ<rt>4</rt></ruby><ruby>一<rt>1</rt></ruby></strong></span>気に 真珠湾）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">第二次世界大戦終結（ドイツ・日本の降伏）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1945</strong></span>］（日独に <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>説<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>よ<rt>4</rt></ruby><ruby>降<rt>5</rt></ruby></strong></span>伏）</p></blockquote>\n<p>第二次世界大戦が終わって、いよいよ次回から戦後史だよ。学校とかではなかなかやらない範囲かもしれないけど、最近の入試ではバンバン出題されているから、最後までしっかり<ruby>頑張<rt>がんば</rt></ruby>ろう！</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "362": "<h2>362</h2>"
};

